//! Genuine inert extraction copies partials and moves full native identities.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://inert-extract.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var parsed=new DOMParser().parseFromString('<body><template id=t><b data-copy=seed>A😀B</b><span>Middle</span><em>End</em></template></body>','text/html'),root=parsed.getElementById('t').content,owner=root.ownerDocument,a=root.firstChild,first=a.firstChild,middle=root.childNodes[1],last=root.lastChild.firstChild,r=owner.createRange();r.setStart(first,1);r.setEnd(last,2);var extract=r.extractContents;");(d,f,p)}
#[test]
fn range_inert_extraction_partial_copies_full_identity_moves_and_native_owners(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var saved={},calls=0;a.author=saved;middle.author=saved;a.addEventListener('check',function(){calls++;});middle.addEventListener('check',function(){calls+=10;});var result=r.extractContents();if(result.nodeType!==11||result.ownerDocument!==owner||result.parentNode!==null||result.childNodes.length!==3||result.textContent!=='😀BMiddleEn'||result.childNodes[1]!==middle||middle.parentNode!==result||middle.author!==saved||root.textContent!=='Ad'||root.childNodes.length!==2)throw 'actual inert partial copies and full identity moves';if(result.firstChild===a||result.firstChild.firstChild===first||result.firstChild.ownerDocument!==owner||result.firstChild.getAttribute('data-copy')!=='seed'||result.firstChild.author!==undefined||a.author!==saved||!r.collapsed||r.startContainer!==root||r.startOffset!==1)throw 'inert independent partial ancestor and specified collapse';result.firstChild.dispatchEvent(new Event('check'));if(calls)throw 'partial inert copy omits listeners';middle.dispatchEvent(new Event('check'));a.dispatchEvent(new Event('check'));if(calls!==11)throw 'actual moved native listener identities';result.firstChild.firstChild.data='Changed';if(first.data!=='A'||last.data!=='d')throw 'independent inert partial data';
"#);}
#[test]
fn range_inert_extraction_exact_character_kinds_collapsed_owner_and_doctype_preflight(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var dataOwner=new Document();for(var node of [dataOwner.createTextNode('\uD800A\uDC00'),dataOwner.createCDATASection('\uD800A\uDC00'),dataOwner.createComment('\uD800A\uDC00'),dataOwner.createProcessingInstruction('target','\uD800A\uDC00')]){var selected=dataOwner.createRange();selected.setStart(node,1);selected.setEnd(node,3);var result=selected.extractContents();if(result.ownerDocument!==dataOwner||result.childNodes.length!==1||result.firstChild===node||result.firstChild.nodeType!==node.nodeType||result.firstChild.data.length!==2||result.firstChild.data.charCodeAt(0)!==65||result.firstChild.data.charCodeAt(1)!==56320||node.data.length!==1||node.data.charCodeAt(0)!==55296||selected.startOffset!==1||!selected.collapsed||node.nodeType===7&&result.firstChild.target!=='target')throw 'exact native inert extraction kinds and PI target';var empty=selected.extractContents();if(empty===result||empty.ownerDocument!==dataOwner||empty.firstChild!==null)throw 'collapsed inert native owner fragment';}
var doc=document.implementation.createHTMLDocument('Extract'),html=doc.documentElement,type=doc.doctype,whole=doc.createRange();whole.selectNodeContents(doc);var caught=false;try{whole.extractContents();}catch(e){caught=e instanceof DOMException&&e.name==='HierarchyRequestError';}if(!caught||doc.documentElement!==html||doc.doctype!==type||whole.startOffset||whole.endOffset!==2||whole.collapsed)throw 'genuine inert selected Doctype refuses before any extraction';whole.setStartAfter(type);var copied=whole.extractContents();if(copied.ownerDocument!==doc||copied.firstChild!==html||html.parentNode!==copied||doc.documentElement!==null||doc.doctype!==type||doc.childNodes.length!==1||!whole.collapsed||whole.startContainer!==doc||whole.startOffset!==1)throw 'genuine inert Document element moves and metadata synchronize';
"#);}
#[test]
fn range_inert_extraction_nested_partials_and_full_template_moves_preserve_content_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var parsedTree=new DOMParser().parseFromString('<body><template id=tree><b><i>Start</i><small>Whole</small></b><template><strong>Nested</strong><script>throw 1</script></template><em><strong>Finish</strong></em></template></body>','text/html'),tree=parsedTree.getElementById('tree').content,full=tree.childNodes[1],nested=full.content,within=tree.firstChild.lastChild,st=tree.firstChild.firstChild.firstChild,en=tree.lastChild.firstChild.firstChild,slice=tree.ownerDocument.createRange();slice.setStart(st,2);slice.setEnd(en,2);var result=slice.extractContents();if(tree.textContent!=='Stnish'||result.textContent!=='artWholeFi'||result.childNodes[1]!==full||full.content!==nested||nested.textContent!=='Nestedthrow 1'||result.firstChild.lastChild!==within||within.parentNode!==result.firstChild||result.firstChild.nodeName!=='B'||result.firstChild.firstChild.nodeName!=='I'||result.lastChild.firstChild.nodeName!=='STRONG'||result.ownerDocument!==tree.ownerDocument||slice.startContainer!==tree||slice.startOffset!==1||!slice.collapsed)throw 'nested partial copies and moved actual template content';
"#);assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.has_navigation_request());}
#[test]
fn range_inert_extraction_ordered_observers_live_aliases_fixed_and_iterator_adjustment(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var obs=new MutationObserver(function(){throw 'drained';});obs.observe(root,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});var live=r.cloneRange(),fixed=new StaticRange({startContainer:first,startOffset:1,endContainer:last,endOffset:2}),inside=owner.createRange();inside.selectNodeContents(middle.firstChild);var iterator=owner.createNodeIterator(root);while(iterator.nextNode()!==middle){}var result=r.extractContents(),records=obs.takeRecords();if(records.length!==3||records[0].target!==first||records[0].oldValue!=='A😀B'||records[1].type!=='childList'||records[1].target!==root||records[1].removedNodes[0]!==middle||records[2].target!==last||records[2].oldValue!=='End'||middle.parentNode!==result)throw 'ordered real inert extraction observations';if(live.startContainer!==first||live.startOffset!==1||live.endContainer!==last||live.endOffset||inside.startContainer!==root||inside.startOffset!==1||!inside.collapsed||fixed.startContainer!==first||fixed.endContainer!==last||fixed.endOffset!==2||iterator.referenceNode===middle||iterator.nextNode()!==root.lastChild)throw 'native inert extraction live fixed iterator integration';
"#);}
#[test]
fn range_inert_extraction_plan_resource_refusal_preserves_native_source_and_recovers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();p.begin_job();let before=(p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end,p.state.retained,p.state.inert_documents.backing_bytes());let limit=p.state.retained_limit;match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>{p.state.host_work=4096;p.state.execution_deadline=Some(Instant::now());}}assert!(p.runtime.execute("extract.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end,p.state.retained,p.state.inert_documents.backing_bytes()),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(root.textContent!=='A😀BMiddleEnd'||middle.parentNode!==root)throw 'initial inert extraction refusal preserves native source';var result=extract.call(r);if(root.textContent!=='Ad'||result.childNodes[1]!==middle||!r.collapsed)throw 'fresh native inert extraction recovery';");}
}

#[test]
fn range_inert_extraction_native_plan_backing_and_captured_origin_refusal_refund_with_recovery(){
 let(mut d,mut f,mut p)=fixture();p.begin_job();let handle=match p.runtime.execute("r",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap(){Value::Host(node)=>node,_=>panic!("native range")};
 let retained=p.state.retained;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let plan=bridge.range_extract_plan(handle).unwrap_or_else(|_|panic!("native extraction plan"));let bytes=plan.steps.capacity()*size_of::<crate::javascript::range_interface::ExtractStep>()+plan.slots.capacity()*size_of::<Option<u32>>();assert_eq!(plan.bytes,bytes);assert_eq!(bridge.state.retained,retained+bytes);drop(plan);bridge.finish_range_extract(bytes);assert_eq!(bridge.state.retained,retained);
 run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,foreignExtract=w.Range.prototype.extractContents;");let before=(p.state.retained,p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);
 p.set_location(&crate::navigation::address("https://foreign.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("foreignExtract.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);
 p.set_location(&crate::navigation::address("https://inert-extract.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"var result=foreignExtract.call(r);if(result.childNodes[1]!==middle||root.textContent!=='Ad'||!r.collapsed)throw 'native extraction origin recovery';");
}

#[test]
fn range_inert_extraction_late_copy_refusal_preserves_committed_data_and_move_prefixes(){
 let mut data_prefix=false;let mut moved_prefix=false;
 for budget in (0..16384).step_by(8){
  let(mut d,mut f,mut p)=fixture();p.begin_job();p.state.copy_work=budget;
  let result=p.runtime.execute("extract.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state});if result.is_ok(){continue;}
  p.begin_job();let status=p.runtime.execute("first.data==='A' && last.data==='End' && r.collapsed",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();if !matches!(status,Value::Bool(true)){continue;}
  let moved=p.runtime.execute("middle.parentNode!==root",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();let moved=matches!(moved,Value::Bool(true));
  if moved{if moved_prefix{continue;}moved_prefix=true;}else{if data_prefix{continue;}data_prefix=true;}
  run(&mut d,&mut f,&mut p,"var preservedParent=middle.parentNode;if(r.startContainer!==root||r.startOffset!==1)throw 'specified extraction collapse retained';r.setStart(first,1);r.setEnd(last,2);var recovered=extract.call(r);if(root.textContent!=='Ad'||!r.collapsed)throw 'late extraction refusal fresh recovery';if(preservedParent!==root&&middle.parentNode!==preservedParent)throw 'already moved native identity is not rolled back';");
  if data_prefix&&moved_prefix{break;}
 }
 assert!(data_prefix&&moved_prefix,"late refusal witnesses: data={data_prefix} moved={moved_prefix}");
}
